package io.strimzi.kafka.bridge.configuration;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * Annotation marking a test class that needs the Kafka cluster to be deployed with TLS enabled
 * (mutual TLS on the client listener, with certificates generated by the Strimzi test container).
 * When this annotation is present, {@code KafkaExtension} starts the cluster with TLS and the
 * client TLS configuration (truststore and keystore generated by the cluster) is propagated
 * to the Bridge and to the test clients.
 */
@Target(ElementType.TYPE)
@Retention(RetentionPolicy.RUNTIME)
public @interface KafkaTlsConfiguration {
}
